// Tools live under both /tools (embedded in the portfolio, full Navbar) and
// /toolbox (standalone, no portfolio chrome — see StandaloneToolsLayout).
// Internal tool links resolve against whichever base the visitor is
// currently on, so navigating within one "world" never drops you into the
// other's chrome.
export function getToolsBasePath(pathname: string): '/tools' | '/toolbox' {
  return pathname === '/toolbox' || pathname.startsWith('/toolbox/') ? '/toolbox' : '/tools';
}

export function getToolPath(slug: string, basePath: string = '/tools'): string {
  return `${basePath}/${slug}`;
}

export function getTool(slug: string): ToolMeta | undefined {
  return tools.find((tool) => tool.slug === slug);
}
